"""Prepare reproducible prompts and project-art references for the authorized CLI."""
from pathlib import Path
from PIL import Image

root = Path(__file__).resolve().parent
art = root.parent
ref = Image.new('RGB', (1024, 512), '#cfcbc0')
for i, name in enumerate(('boy', 'girl')):
    im = Image.open(art / 'revision4' / f'{name}-frame-0.png').convert('RGBA')
    im.thumbnail((490, 480))
    ref.paste(im, (i * 512 + (512-im.width)//2, (512-im.height)//2), im)
ref.save(root/'reference-children.png')

style = 'Cinematic practical tokusatsu miniature craftsmanship, realistic painted resin and fabric texture, restrained manga ink contours, sophisticated hand-painted lighting; match our existing game. Not chibi, not flat vector. '
grid = 'EXACT 4 columns by 2 rows of equal square cells in a 2048x1024 sheet. Seven occupied cells in reading order; last lower-right cell empty. No labels, borders or text. Entire subject/effects inside each cell with 30px safety margins. Flat exact #FF00FF chroma background. '
prompts = {
'gamera': 'Use case: identity-preserve. Input image 1 is the USER SHAPE REFERENCE; input image 2 is STYLE reference only. Replace the inaccurate round flat shell with the unmistakable reference shape: an elongated, high DOMED olive-green turtle carapace, layered large triangular/leaf-like overlapping scutes, central raised keel and pointed scalloped rear edge. All head, tail and limbs completely tucked inside. Four pale cyan CURVED SICKLE-LIKE FLAME STREAMS curl around the shell in one rotation direction, like the reference; NOT four straight little rocket nozzles, no mechanical rings. Fixed elevated three-quarter camera sees substantial shell thickness, dark underside and distinct oval length. Seven true views through one continuous yaw rotation: 0,51,103,154,206,257,309 degrees. Preserve dome height, olive palette and longitudinal scute pattern; do not substitute an in-plane flat disc spinning sprite. '+style+grid,
'cloud': 'Use case: precise-object-edit. Image 1 is the USER LIGHTNING SHAPE REFERENCE; image 2 is our cloud sheet edit target. Keep the charcoal cloud but make enormous expressive branching GOLD ELECTRICAL ARCS. Cloud body occupies only central 45% of each cell width. Rays spread across 90% of cell width and height. At least three bright main branches leave the TOP, and two from EACH MIDDLE SIDE. Each ray has 4-7 strongly kinked bends plus smaller branching forks, as in reference, curling back and out instead of straight radial spokes. Thick brilliant ivory-gold cores, amber layered glow, smaller hairline branches. Top and middle arcs as strong as lower arcs. Seven frames build from flickering arcs to a huge discharge then diminish, with visible arcs in every frame; never just ordinary downward lightning. Do not draw the dragons or any poster text. '+style+grid,
'oilrig': 'Use case: precise-object-edit. Input is our Godzilla skyward breath sprite sheet. Keep exact Godzilla identity, upright head-tilted-up pose and feet anchor. Make blue atomic breath 2 TIMES THICKER and 1.7 TIMES LONGER relative to the body: blue-white core and ragged cyan plasma sheath. Beam extends vertically to sky; torso remains heavy and imposing. Seven sequential frames charge, powerful beam ignition, stronger pulse, strongest pulse, pulse, fading beam, charge. Preserve sufficient room above head and ALL beam tips within cells; no cropped beam. '+style+grid,
'ground': 'Use case: stylized-concept. Input is existing game scenery STYLE reference. Create THREE DIFFERENT side-scrolling TOKUSATSU STUDIO FLOOR strips stacked vertically in exactly three equal horizontal rows in a 1536x1536 image. Each row 1536x512 is one continuous side-on foreground floor scene. Top 20% of each row is PURE #FF00FF empty chroma above irregular prop silhouettes; floor begins around y=180 in every row and fills to bottom. Row1: prop warehouse clutter, wooden crates, foam miniature building facades, rolled painted backdrops, stacked monster suit molds. Row2: filming equipment, vintage cinema cameras on dollies, tripods, cable coils, lamps, sandbags, road cases. Row3: set construction workshop, timber flats, spare miniature rooftops, paint cans, tires, wheeled racks and folded canvas. Spread interesting clusters throughout the WHOLE width; no large blank stretches. All rows share the same textured dusty warm-charcoal concrete floor, level perspective and lighting so they can mix in a loop. LEFT and RIGHT 100px of every strip have compatible sparse cables, small crates and same floor color, no large object cut at edges. Objects stay mostly in upper half; lower half detailed scuffed floor with cables and small scattered props. No people, no readable writing, no logos, no borders. '+style
}
endings = {
'canvas': ('a tall wooden frame holding an INTACT painted pale-blue sky canvas', '1 intact canvas and NO child; 2 canvas bulges from the child hitting from behind; 3 a small central star-shaped tear opens with fabric flaps; 4 forehead and hat/goggles peek through; 5 the whole HEAD and shoulders poke through the hole; 6 child looks aside with a small embarrassed smile and blush; 7 same child head through torn canvas gives a timid little wave and sheepish smile. Do not show an already torn canvas in frame 1.'),
'anguirus': ('a friendly low crouching Anguirus with a rugged spiked olive shell', '1 monster alone, no child; 2 child softly lands on the back; 3 a shell spike hooks the BACKPACK strap; 4 child hangs safely upright by the backpack with feet dangling; 5 legs swing slightly; 6 child gives a sheepish smile; 7 monster glances back while child makes a small friendly wave. Clothing stays completely intact, no underwear, no injury.'),
'sand': ('a shallow rectangular miniature sand tray with a giant three-toed monster footprint', '1 sand tray alone; 2 child tumbles softly into the sand; 3 a small sand puff hides the face; 4 boots point upward in comic headfirst landing; 5 legs kick gently; 6 child sits up dusty but unharmed; 7 child brushes sand off cheek with small embarrassed grin. Friendly slapstick, no danger or injury.'),
'tower': ('an intact red-and-ivory miniature Tokyo Tower on a small base', '1 intact tower alone; 2 child lands seated on the upper flexible section; 3 tower bends softly sideways like rubber; 4 it folds into a safe chair-like angle; 5 child steadies themself; 6 sits smiling sheepishly; 7 makes a small V-sign, seated safely on the bent miniature tower. No sharp wreckage or injury.'),
'ultraman': ('a seated friendly silver-and-red Ultra hero holding a takeout tea cup, practical actor suit', '1 hero alone with tea; 2 child enters the outstretched catching arms; 3 hero safely catches child in lap, tea wobbles; 4 hero steadies cup while startled; 5 child looks up amused; 6 both relax; 7 child gives a shy smile and little wave while safely cradled. Preserve hero and tea throughout.'),
'water': ('a small rectangular blue miniature filming water tank with one tiny toy submarine', '1 still tank alone; 2 child enters feet-first; 3 harmless big blue-white splash; 4 child surfaces smiling with face above water; 5 toy submarine balances on head; 6 droplets fall; 7 child gives a sheepish smile and tiny wave with submarine still on head. No drowning, calm shallow tank.'),
'dolly': ('a vintage motion-picture camera and seat mounted on a low four-wheel rail dolly', '1 camera dolly alone; 2 child slides gently into the assistant seat; 3 cart rolls slightly; 4 child catches the camera crank; 5 cart slows; 6 child looks surprised at camera; 7 seated child smiles shyly and waves as honorary assistant director. Camera remains recognizable and cart undamaged.'),
'chair': ('a wooden folding director chair with canvas seat, megaphone and a few storyboard papers', '1 upright chair alone; 2 child lands in seat; 3 chair tips backward; 4 folds safely down low with child still seated; 5 papers flutter and megaphone tilts; 6 child looks around embarrassed; 7 child sits amid scattered papers and gives a small sheepish wave. No injury, no exposed clothing, no adults needed.')
}
for name,(prop,action) in endings.items():
    prompts['ending-'+name] = ('Use case: illustration-story. Asset type: TWO-GENDER seven-frame ending animation atlas. Input 1 contains the two EXACT child character identity references; input 2 is the prop/style reference. '+
    'EXACT GRID: SEVEN equal columns and TWO rows in a 3072x1024 image; FOURTEEN cells total. Top row is the RED BASEBALL CAP BOY in red vest/yellow shirt/dark trousers. Bottom row repeats the SAME SEVEN actions with the GOGGLE-WEARING GIRL from the reference, same outfit palette and goggles; do not turn her into the boy. '+
    'In each row the PROP stays exactly the same position, size and feet baseline through all seven cells; no camera moves. First cell has only the intact prop with NO CHILD. Prop: '+prop+'. Sequence left to right: '+action+' '+
    'Final two frames show small natural smiles, never wide laughing mouths. Frame 1 is used directly as the game collision prop. Whole scene and all effects contained inside each cell with 20px clear margins. Constant scale, fixed three-quarter side view. Only one child per occupied action frame, no duplicate limbs, no clone trails. Pure uniform #FF00FF background everywhere outside the isolated scene, no floor rectangle, no text, no labels, no grid lines. '+style)
stages = [('day','blue-grey daylight sky with soft ivory clouds','distant muted mountains and very small studio skyline','detailed Japanese miniature city rooftops and studio warehouse silhouettes'),('sunset','warm terracotta sunset sky and ochre clouds','hazy copper mountains and distant miniature skyline','dark terracotta miniature buildings and warehouse roofs'),('night','inky blue night sky with restrained small stars and wispy clouds','dim blue mountains and sparse distant lit towers','Japanese miniature city rooftops with subtle warm windows'),('moon','charcoal cosmic sky with a few fine stars and pale dust clouds','muted grey lunar ridges and a small distant earth prop','detailed lunar miniature set ridges and low studio lunar-base structures')]
for name,sky,far,near in stages:
    prompts['parallax-'+name] = ('Use case: stylized-concept. Input is our existing '+name+' background STYLE reference. Reconstruct it as THREE SEPARATE PARALLAX LAYERS stacked in three equal rows of a 1536x1536 sheet, each row 1536x512. Row1: opaque full-bleed '+sky+', NO buildings or ground. Row2: '+far+', rising only from bottom edge to at most half row height; PURE #FF00FF everywhere above silhouettes, no sky. Row3: '+near+', from bottom edge to varied roofline between 180-350px; PURE #FF00FF above silhouettes, no sky. Rows 2 and 3 must be separate clean cutouts, not rectangular landscape paintings. LEFT and RIGHT edges each match in level and color for horizontal looping. Each row is a full panoramic layer, no dividing lines, labels, text or giant creatures. Match existing palette and handmade film-set materials. '+style)
for name,prompt in prompts.items(): (root/f'{name}-prompt.txt').write_text(prompt,encoding='utf-8')
for name,source in [('day',art/'production_sample'/'city.webp'),('sunset',art/'full_assets'/'stage2.webp'),('night',art/'full_assets'/'stage3.webp'),('moon',art/'full_assets'/'stage4.webp')]: Image.open(source).convert('RGB').save(root/f'reference-{name}.png')
for name in endings: Image.open(art/'full_assets'/f'{name}.webp').convert('RGBA').save(root/f'reference-{name}.png')
print('Prepared 16 prompts and identity/scenery references.')
